using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using RoadGunner;using RoadGunner.Editor;
public static class LevelEditorDuplicateChecks{public static string Main(){var l=RoadGunnerLevelAuthoring.Current;var source=l.session.spawns.authoredRaiders[0];Selection.activeGameObject=source.gameObject;if(!EditorApplication.ExecuteMenuItem("Edit/Duplicate"))throw new Exception("Unity duplicate menu unavailable");var duplicate=Selection.activeGameObject.GetComponent<Raider>();RoadGunnerLevelAuthoring.Wire(l);bool ok=duplicate&&duplicate!=source&&duplicate.tuning!=source.tuning&&duplicate.tuning.enemyHealth==60&&l.session.spawns.authoredRaiders.Length==5;string path=AssetDatabase.GetAssetPath(duplicate.tuning);duplicate.tuning.enemyHealth=90;EditorUtility.SetDirty(duplicate.tuning);bool isolated=source.tuning.enemyHealth==60;Undo.DestroyObjectImmediate(duplicate.gameObject);RoadGunnerLevelAuthoring.Wire(l);RoadGunnerLevelAuthoring.Save(l);EditorSceneManager.OpenScene(RoadGunnerLevelEditorChecks.Demo);if(path!="Assets/RoadGunner/Scenes/LevelEditor_Demo_Data/Enemy Overrides/Wasteland Raider.asset")AssetDatabase.DeleteAsset(path);string text=(ok?"PASS ":"FAIL ")+"Unity Cmd-D preserves prefab and creates an independent level override\n"+(isolated?"PASS ":"FAIL ")+"Duplicated enemy stats do not change source\n";File.WriteAllText(RoadGunnerLevelEditorChecks.Folder+"/DuplicateChecks.txt",text);return text;}}
